(301100,1,21600,0,'Scout Gyrospire Beza','Climb Gyrospire Beza and scout its key rooms, then deal with the Chamberlain.','Experience','79735',0,250000,0,0,0,70,0,0,1,6,0,1190,'',0,0,0,0,6130,-1,18,1),
(301101,1,21600,0,'How Does Your Garden Grow','Raze the spire gardens of Gyrospire Beza and destroy whatever grows back.','Experience','79736',0,250000,0,0,0,70,0,0,1,6,0,1190,'',0,0,0,0,6131,-1,18,1),
(301102,1,21600,0,'Sand in the Gears','Hunt the shock steamworks of Gyrospire Beza and break their commanders.','Experience','79737',0,250000,0,0,0,70,0,0,1,6,0,1190,'',0,0,0,0,6132,-1,18,1),
(301103,1,21600,0,'End the Return','Cut Gyrospire Beza\'s fuel supply: find the ember, tap the oil, and destroy the fuelmasters.','Experience','79738',0,250000,0,0,0,70,0,0,1,6,0,1190,'',0,0,0,0,6133,-1,18,1),
(301104,1,21600,0,'It\'s All in Your Head','The most direct of missions: kill everything that matters on Gyrospire Beza.','Experience','79739',0,250000,0,0,0,70,0,0,1,6,0,1190,'',0,0,0,0,6134,-1,18,1),
(301105,1,21600,0,'Did We Forget the Cheese','Contaminate the spire stores of Gyrospire Zeka and ruin the Chamberlain\'s day.','Experience','79740',0,250000,0,0,0,70,0,0,1,6,0,1190,'',0,0,0,0,6135,-1,25,1),
(301106,1,21600,0,'To Climb a Spire','Walk every room of Gyrospire Zeka and map the climb.','Experience','79741',0,250000,0,0,0,70,0,0,1,6,0,1190,'',0,0,0,0,6136,-1,25,1),
(301107,1,21600,0,'Intelligence Gathering','Scout the basement and the peak of Gyrospire Zeka, and silence Engineer XXXIX.','Experience','79741',0,250000,0,0,0,70,0,0,1,6,0,1190,'',0,0,0,0,6137,-1,25,1),
(301108,1,21600,0,'Cut Off the Head','Foul the spire\'s oil and coal, smudge the schematics, and take Captain Gearwell.','Experience','79742',0,250000,0,0,0,70,0,0,1,6,0,1190,'',0,0,0,0,6138,-1,25,1),
(301109,1,21600,0,'You Might Poke an Eye Out','Bomb Gyrospire Zeka from basement to roof.','Experience','79744',0,250000,0,0,0,70,0,0,1,6,0,1190,'',0,0,0,0,6139,-1,25,1),
(301110,1,21600,0,'Deception and Interception','Slip into the S.H.I.P. workshop, disguise yourself, and intercept the couriers.','Experience','79745',0,250000,0,0,0,70,0,0,1,6,0,1190,'',0,0,0,0,6140,-1,25,1),
(301111,1,21600,0,'S.H.I.P Sabotage','Smuggle parts to Cledmire, then blow the workshop boilers.','Experience','79746',0,250000,0,0,0,70,0,0,1,6,0,1190,'',0,0,0,0,6141,-1,25,1),
(301112,1,21600,0,'Mechalossus','Something huge sleeps in the workshop. Wake it. Kill it.','Experience','79747',0,250000,0,0,0,70,0,0,1,6,0,1190,'',0,0,0,0,6142,-1,25,1),
