-- mission ground spawns (oil/coal/bombs for the Zeka objectives)
DELETE FROM `ground_spawns` WHERE `id` BETWEEN 1520007410 AND 1520007419;

-- Cleaning Fluid rides the zeka cleaning oozes + skitterers (Cut Off the Head)
SELECT DISTINCT le.lootdrop_id, 34996, 1, 0, 20 FROM npc_types n
JOIN loottable_entries le ON le.loottable_id = n.loottable_id
WHERE n.id IN (441012,441023,441033,441052,441000,441007,441015)
  AND n.loottable_id > 0
  AND NOT EXISTS (SELECT 1 FROM lootdrop_entries de WHERE de.lootdrop_id = le.lootdrop_id AND de.item_id = 34996);
